function(container, apiUrl, tables) {
  const docTypeSelect = container.querySelector("#doc-type");
  const docNameSelect = container.querySelector("#doc-name");
  const version1Select = container.querySelector("#version1");
  const version2Select = container.querySelector("#version2");
  const btnCompare = container.querySelector("#btn-compare");
  const btnReset = container.querySelector("#btn-reset");
  const comparisonArea = container.querySelector("#comparison-area");
  const emptyState = container.querySelector("#empty-state");
  const metadataPanel = container.querySelector("#metadata-panel");
  const legendPanel = container.querySelector("#legend-panel");
  const v1Content = container.querySelector("#version1-content");
  const v2Content = container.querySelector("#version2-content");

  let contractVersions = [];
  let proposalVersions = [];
  let contractData = [];
  let proposalData = [];
  let userMap = {};

  // ユーザーマップを構築
  async function buildUserMap() {
    if (tables.length > 0 && tables[0].tableName === "ユーザー") {
      tables[0].records.forEach(u => {
        userMap[u.ユーザーID] = u.氏名 || u.ユーザー名 || "不明";
      });
    }
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      buildUserMap();

      // 契約書バージョン取得（tableIndex推定: 契約書バージョン）
      const contractVersionsData = await window.aivicApi.list(4); // 契約書バージョン
      if (contractVersionsData) {
        contractVersions = contractVersionsData;
      }

      // 提案資料バージョン取得（tableIndex推定: 提案資料バージョン）
      const proposalVersionsData = await window.aivicApi.list(5); // 提案資料バージョン
      if (proposalVersionsData) {
        proposalVersions = proposalVersionsData;
      }

      // 契約書マスタ取得
      const contractsData = await window.aivicApi.list(1); // 契約書
      if (contractsData) {
        contractData = contractsData;
      }

      // 提案資料マスタ取得
      const proposalsData = await window.aivicApi.list(2); // 提案資料
      if (proposalsData) {
        proposalData = proposalsData;
      }
    } catch (e) {
      console.error("データ読み込みエラー:", e);
    }
  }

  // ドキュメント種別変更時
  docTypeSelect.addEventListener("change", () => {
    docNameSelect.innerHTML = '<option value="">選択してください</option>';
    version1Select.innerHTML = '<option value="">選択してください</option>';
    version2Select.innerHTML = '<option value="">選択してください</option>';

    const docType = docTypeSelect.value;
    if (docType === "contract") {
      contractData.forEach(c => {
        const opt = document.createElement("option");
        opt.value = c.契約書ID;
        opt.textContent = c.契約書名 || "無名";
        docNameSelect.appendChild(opt);
      });
    } else if (docType === "proposal") {
      proposalData.forEach(p => {
        const opt = document.createElement("option");
        opt.value = p.提案資料ID;
        opt.textContent = p.提案資料名 || "無名";
        docNameSelect.appendChild(opt);
      });
    }
  });

  // ドキュメント名変更時
  docNameSelect.addEventListener("change", () => {
    version1Select.innerHTML = '<option value="">選択してください</option>';
    version2Select.innerHTML = '<option value="">選択してください</option>';

    const docType = docTypeSelect.value;
    const docId = docNameSelect.value;

    if (!docId) return;

    let versions = [];
    if (docType === "contract") {
      versions = contractVersions.filter(v => v.契約書ID === docId);
    } else if (docType === "proposal") {
      versions = proposalVersions.filter(v => v.提案資料ID === docId);
    }

    versions.sort((a, b) => (a.バージョン番号 || 0) - (b.バージョン番号 || 0));

    versions.forEach(v => {
      const opt1 = document.createElement("option");
      opt1.value = v.バージョンID;
      opt1.textContent = `v${v.バージョン番号} (${new Date(v.作成日時).toLocaleDateString()})`;
      version1Select.appendChild(opt1);

      const opt2 = document.createElement("option");
      opt2.value = v.バージョンID;
      opt2.textContent = `v${v.バージョン番号} (${new Date(v.作成日時).toLocaleDateString()})`;
      version2Select.appendChild(opt2);
    });
  });

  // 差分計算（簡易版：単語ベース）
  function calculateDiff(text1, text2) {
    const words1 = text1.split(/\s+/);
    const words2 = text2.split(/\s+/);

    const result1 = [];
    const result2 = [];

    // 簡易的な差分検出（LCS的アプローチの簡略版）
    const maxLen = Math.max(words1.length, words2.length);
    for (let i = 0; i < maxLen; i++) {
      const w1 = words1[i] || "";
      const w2 = words2[i] || "";

      if (w1 === w2) {
        result1.push(w1);
        result2.push(w2);
      } else if (!w1) {
        result2.push(`<span class="added">${w2}</span>`);
      } else if (!w2) {
        result1.push(`<span class="deleted">${w1}</span>`);
      } else {
        result1.push(`<span class="changed">${w1}</span>`);
        result2.push(`<span class="changed">${w2}</span>`);
      }
    }

    return {
      html1: result1.join(" "),
      html2: result2.join(" ")
    };
  }

  // 比較実行
  btnCompare.addEventListener("click", async () => {
    const docType = docTypeSelect.value;
    const docId = docNameSelect.value;
    const v1Id = version1Select.value;
    const v2Id = version2Select.value;

    if (!docType || !docId || !v1Id || !v2Id) {
      alert("ドキュメント種別、ドキュメント名、バージョンをすべて選択してください");
      return;
    }

    if (v1Id === v2Id) {
      alert("異なるバージョンを選択してください");
      return;
    }

    let v1Data, v2Data;

    if (docType === "contract") {
      v1Data = contractVersions.find(v => v.バージョンID === v1Id);
      v2Data = contractVersions.find(v => v.バージョンID === v2Id);
    } else {
      v1Data = proposalVersions.find(v => v.バージョンID === v1Id);
      v2Data = proposalVersions.find(v => v.バージョンID === v2Id);
    }

    if (!v1Data || !v2Data) {
      alert("バージョンデータが見つかりません");
      return;
    }

    // メタデータ表示
    container.querySelector("#v1-created").textContent = new Date(v1Data.作成日時).toLocaleString();
    container.querySelector("#v1-creator").textContent = userMap[v1Data.作成者ID] || "不明";
    container.querySelector("#v1-status").textContent = v1Data.ステータス || "-";

    container.querySelector("#v2-created").textContent = new Date(v2Data.作成日時).toLocaleString();
    container.querySelector("#v2-creator").textContent = userMap[v2Data.作成者ID] || "不明";
    container.querySelector("#v2-status").textContent = v2Data.ステータス || "-";

    // コンテンツ取得（ファイルパスまたは内容フィールド）
    const content1 = docType === "contract" ? (v1Data.ファイルパス || v1Data.変更内容 || "") : (v1Data.内容 || "");
    const content2 = docType === "contract" ? (v2Data.ファイルパス || v2Data.変更内容 || "") : (v2Data.内容 || "");

    // 差分計算
    const diff = calculateDiff(content1, content2);

    // 表示
    v1Content.innerHTML = diff.html1;
    v2Content.innerHTML = diff.html2;

    emptyState.style.display = "none";
    comparisonArea.style.display = "grid";
    metadataPanel.style.display = "block";
    legendPanel.style.display = "flex";
  });

  // リセット
  btnReset.addEventListener("click", () => {
    docTypeSelect.value = "";
    docNameSelect.innerHTML = '<option value="">選択してください</option>';
    version1Select.innerHTML = '<option value="">選択してください</option>';
    version2Select.innerHTML = '<option value="">選択してください</option>';
    v1Content.innerHTML = "";
    v2Content.innerHTML = "";

    emptyState.style.display = "flex";
    comparisonArea.style.display = "none";
    metadataPanel.style.display = "none";
    legendPanel.style.display = "none";
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const contractVersionIdx = tables.findIndex(t => t.tableName === "契約書バージョン");
  const proposalVersionIdx = tables.findIndex(t => t.tableName === "提案資料バージョン");
  const changeHistoryIdx = tables.findIndex(t => t.tableName === "変更履歴");
  const contractIdx = tables.findIndex(t => t.tableName === "契約書");
  const proposalIdx = tables.findIndex(t => t.tableName === "提案資料");
  const userIdx = tables.findIndex(t => t.tableName === "ユーザー");

  let selectedDocId = null;
  let selectedDocType = null;
  let uploadedFile = null;
  let allDocuments = [];

  // 1. 資料一覧を描画
  function renderDocList(docs) {
    const listEl = container.querySelector("#doc-list");
    listEl.innerHTML = docs.map(doc => `
      <button class="doc-item" data-id="${doc.id}" data-type="${doc.type}" style="
        padding: 8px;
        border: 1px solid rgba(255,255,255,0.12);
        background: rgba(0,0,0,0.15);
        color: var(--text);
        border-radius: 3px;
        text-align: left;
        cursor: pointer;
        font-size: 12px;
        transition: all 0.2s;
      ">
        <div style="font-weight: 600; margin-bottom: 2px;">${doc.name || "—"}</div>
        <div style="font-size: 11px; color: var(--text-muted);">v${doc.currentVersion || "—"}</div>
      </button>
    `).join("");
  }

  // 2. 変更履歴を描画
  function renderHistory(historyRows) {
    const histEl = container.querySelector("#history-list");
    const limited = historyRows.slice(0, 5);
    histEl.innerHTML = limited.map(h => `
      <div style="padding: 6px; background: rgba(0,0,0,0.15); border-radius: 3px; font-size: 11px;">
        <div style="color: #d4af37; font-weight: 600; margin-bottom: 2px;">${h.変更種別 || "—"}</div>
        <div style="color: var(--text-muted);">${h.変更理由 || h.変更フィールド || "—"}</div>
        <div style="color: var(--text-muted); font-size: 10px; margin-top: 2px;">${new Date(h.作成日時).toLocaleString("ja-JP")}</div>
      </div>
    `).join("") || '<div style="color: var(--text-muted); font-size: 12px;">履歴なし</div>';
  }

  // 3. 資料詳細を表示
  function showDocDetail(docId, docType) {
    selectedDocId = docId;
    selectedDocType = docType;
    uploadedFile = null;
    container.querySelector("#file-name").textContent = "";

    let doc = null;
    if (docType === "contract") {
      const versions = tables[contractVersionIdx]?.records || [];
      doc = versions.find(v => v.契約書ID === docId);
    } else if (docType === "proposal") {
      const versions = tables[proposalVersionIdx]?.records || [];
      doc = versions.find(v => v.提案資料ID === docId);
    }

    if (doc) {
      const docName = docType === "contract" 
        ? (tables[contractIdx]?.records || []).find(c => c.契約書ID === docId)?.契約書名 || "—"
        : (tables[proposalIdx]?.records || []).find(p => p.提案資料ID === docId)?.提案資料名 || "—";

      container.querySelector("#current-doc-name").textContent = docName;
      container.querySelector("#current-version").textContent = `v${doc.バージョン番号 || "—"}`;
      container.querySelector("#current-status").textContent = doc.ステータス || "—";

      // 変更者・日時を現在ユーザーで埋める（実装簡略化）
      const now = new Date();
      container.querySelector("#changer-name").textContent = "現在のユーザー";
      container.querySelector("#changer-date").textContent = now.toLocaleString("ja-JP");

      // 変更履歴を表示
      const history = (tables[changeHistoryIdx]?.records || []).filter(h => h.対象ID === docId);
      renderHistory(history);
    }
  }

  // 4. 初期データ読み込み
  async function loadInitialData() {
    const contracts = tables[contractIdx]?.records || [];
    const proposals = tables[proposalIdx]?.records || [];
    const contractVersions = tables[contractVersionIdx]?.records || [];
    const proposalVersions = tables[proposalVersionIdx]?.records || [];

    // 資料一覧を構築
    allDocuments = [
      ...contracts.map(c => ({
        id: c.契約書ID,
        name: c.契約書名,
        type: "contract",
        currentVersion: (contractVersions.filter(v => v.契約書ID === c.契約書ID).sort((a, b) => b.バージョン番号 - a.バージョン番号)[0]?.バージョン番号) || 1
      })),
      ...proposals.map(p => ({
        id: p.提案資料ID,
        name: p.提案資料名,
        type: "proposal",
        currentVersion: (proposalVersions.filter(v => v.提案資料ID === p.提案資料ID).sort((a, b) => b.バージョン番号 - a.バージョン番号)[0]?.バージョン番号) || 1
      }))
    ];

    renderDocList(allDocuments);
  }

  // 5. フィルタ処理
  container.querySelector("#doc-type-filter").addEventListener("change", (e) => {
    const type = e.target.value;
    const filtered = type ? allDocuments.filter(d => d.type === type) : allDocuments;
    renderDocList(filtered);
  });

  // 6. 資料選択
  container.addEventListener("click", (e) => {
    const docBtn = e.target.closest(".doc-item");
    if (docBtn) {
      const docId = docBtn.dataset.id;
      const docType = docBtn.dataset.type;
      showDocDetail(docId, docType);
    }
  });

  // 7. ファイルアップロード
  const uploadZone = container.querySelector("#upload-zone");
  const fileInput = container.querySelector("#file-input");
  const fileBrowseBtn = container.querySelector("#file-browse-btn");

  fileBrowseBtn.addEventListener("click", () => fileInput.click());

  fileInput.addEventListener("change", (e) => {
    if (e.target.files.length > 0) {
      uploadedFile = e.target.files[0];
      container.querySelector("#file-name").textContent = `✓ ${uploadedFile.name}`;
    }
  });

  uploadZone.addEventListener("dragover", (e) => {
    e.preventDefault();
    uploadZone.style.borderColor = "#d4af37";
    uploadZone.style.background = "rgba(212,175,55,0.1)";
  });

  uploadZone.addEventListener("dragleave", () => {
    uploadZone.style.borderColor = "rgba(212,175,55,0.4)";
    uploadZone.style.background = "transparent";
  });

  uploadZone.addEventListener("drop", (e) => {
    e.preventDefault();
    uploadZone.style.borderColor = "rgba(212,175,55,0.4)";
    uploadZone.style.background = "transparent";
    if (e.dataTransfer.files.length > 0) {
      uploadedFile = e.dataTransfer.files[0];
      container.querySelector("#file-name").textContent = `✓ ${uploadedFile.name}`;
    }
  });

  // 8. 保存ボタン
  container.querySelector("#btn-save").addEventListener("click", async () => {
    if (!selectedDocId) {
      alert("資料を選択してください");
      return;
    }

    const versionNum = container.querySelector("#new-version-num").value;
    const versionName = container.querySelector("#new-version-name").value;
    const changeDesc = container.querySelector("#change-description").value;

    if (!versionNum || !changeDesc) {
      alert("バージョン番号と変更内容は必須です");
      return;
    }

    if (!uploadedFile) {
      alert("ファイルをアップロードしてください");
      return;
    }

    // バージョン情報を保存
    const versionData = {
      [selectedDocType === "contract" ? "契約書ID" : "提案資料ID"]: selectedDocId,
      バージョン番号: parseInt(versionNum),
      タイトル: versionName || `Version ${versionNum}`,
      内容: changeDesc,
      ステータス: "下書き",
      作成者ID: "current-user-id",
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      備考: changeDesc
    };

    const tableIdx = selectedDocType === "contract" ? contractVersionIdx : proposalVersionIdx;
    const saved = await window.aivicApi.save(tableIdx, versionData);

    if (saved) {
      // 変更履歴を記録
      const historyData = {
        対象テーブル: selectedDocType === "contract" ? "契約書" : "提案資料",
        対象ID: selectedDocId,
        変更種別: "バージョン作成",
        変更フィールド: "バージョン番号",
        変更前値: "",
        変更後値: versionNum,
        変更理由: changeDesc,
        作成者ID: "current-user-id",
        作成日時: new Date().toISOString()
      };

      await window.aivicApi.save(changeHistoryIdx, historyData);

      alert("バージョン情報を保存しました");
      container.querySelector("#new-version-num").value = "";
      container.querySelector("#new-version-name").value = "";
      container.querySelector("#change-description").value = "";
      container.querySelector("#file-name").textContent = "";
      uploadedFile = null;

      // 再読み込み
      loadInitialData();
    }
  });

  // 9. キャンセルボタン
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    container.querySelector("#new-version-num").value = "";
    container.querySelector("#new-version-name").value = "";
    container.querySelector("#change-description").value = "";
    container.querySelector("#file-name").textContent = "";
    uploadedFile = null;
  });

  // 10. 変更前後比較ボタン
  container.querySelector("#btn-compare").addEventListener("click", () => {
    if (!selectedDocId) {
      alert("資料を選択してください");
      return;
    }
    window.showScreen("scr-1781954473088");
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#result-tbody");
  const historyPanel = container.querySelector("#history-panel");
  const historyTimeline = container.querySelector("#history-timeline");
  const assigneeSelect = container.querySelector("#select-assignee");

  let allRecords = [];
  let selectedRecordId = null;

  // ===== 1. 再描画関数 =====
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="height: 2rem; text-align: center; color: var(--text-muted);"><td colspan="6">検索結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(r => {
      const type = r.契約種別 || r.提案資料名 ? (r.契約書名 ? '契約書' : '提案資料') : '不明';
      const name = r.契約書名 || r.提案資料名 || '(無名)';
      const status = r.ステータス || '不明';
      const createdDate = r.作成日時 ? new Date(r.作成日時).toLocaleDateString('ja-JP') : '-';
      const updatedDate = r.更新日時 ? new Date(r.更新日時).toLocaleDateString('ja-JP') : '-';

      return `<tr data-id="${r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.2s;">
        <td style="padding: 0.75rem; color: var(--text);">${name}</td>
        <td style="padding: 0.75rem; color: var(--text-muted);">${type}</td>
        <td style="padding: 0.75rem;">
          <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-size: 0.75rem; font-weight: 600; background: ${getStatusColor(status)}; color: #fff;">
            ${status}
          </span>
        </td>
        <td style="padding: 0.75rem; color: var(--text-muted);">${createdDate}</td>
        <td style="padding: 0.75rem; color: var(--text-muted);">${updatedDate}</td>
        <td style="padding: 0.75rem; text-align: center;">
          <button class="action-btn secondary view-detail-btn" data-id="${r.id}" style="padding: 0.375rem 0.75rem; font-size: 0.75rem; margin-right: 0.25rem;">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}" style="padding: 0.375rem 0.75rem; font-size: 0.75rem;">削除</button>
        </td>
      </tr>`;
    }).join("");
  }

  function getStatusColor(status) {
    const colors = {
      '草案': '#6b7280',
      '承認待ち': '#f59e0b',
      '有効': '#10b981',
      '終了': '#6b7280',
      'キャンセル': '#ef4444',
      '下書き': '#6b7280',
      '提案中': '#3b82f6',
      '契約済み': '#10b981',
      '却下': '#ef4444'
    };
    return colors[status] || '#9ca3af';
  }

  // ===== 2. 初期データ読み込み =====
  async function loadInitialData() {
    const contracts = await window.aivicApi.list(0) || [];
    const proposals = await window.aivicApi.list(1) || [];

    allRecords = [...contracts, ...proposals];
    renderRows(allRecords);

    // 担当者リストを populate
    const users = await window.aivicApi.list(2) || [];
    const uniqueUsers = [...new Set(users.map(u => u.氏名))];
    uniqueUsers.forEach(name => {
      const opt = document.createElement('option');
      opt.value = name;
      opt.textContent = name;
      assigneeSelect.appendChild(opt);
    });
  }

  loadInitialData();

  // ===== 3. 検索ボタン =====
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-keyword").value.toLowerCase();
    const typeFilter = container.querySelector("#select-type").value;
    const statusFilter = container.querySelector("#select-status").value;
    const dateFrom = container.querySelector("#input-date-from").value;
    const dateTo = container.querySelector("#input-date-to").value;
    const assigneeFilter = container.querySelector("#select-assignee").value;

    let filtered = allRecords.filter(r => {
      const name = (r.契約書名 || r.提案資料名 || '').toLowerCase();
      const type = r.契約種別 ? '契約書' : '提案資料';
      const status = r.ステータス || '';
      const createdDate = r.作成日時 ? new Date(r.作成日時).toISOString().split('T')[0] : '';

      const matchKeyword = !keyword || name.includes(keyword);
      const matchType = !typeFilter || type === typeFilter;
      const matchStatus = !statusFilter || status === statusFilter;
      const matchDateFrom = !dateFrom || createdDate >= dateFrom;
      const matchDateTo = !dateTo || createdDate <= dateTo;
      const matchAssignee = !assigneeFilter || (r.担当者 === assigneeFilter || r.ユーザーID === assigneeFilter);

      return matchKeyword && matchType && matchStatus && matchDateFrom && matchDateTo && matchAssignee;
    });

    renderRows(filtered);
  });

  // ===== 4. 行クリック（詳細・変更履歴表示） =====
  container.addEventListener("click", async e => {
    const detailBtn = e.target.closest(".view-detail-btn");
    if (detailBtn) {
      selectedRecordId = detailBtn.dataset.id;
      const record = allRecords.find(r => r.id === selectedRecordId);

      if (record) {
        // 変更履歴を取得
        const histories = await window.aivicApi.list(3) || [];
        const recordHistories = histories.filter(h => h.対象ID === selectedRecordId);

        // タイムライン表示
        historyTimeline.innerHTML = recordHistories.map(h => `
          <div style="margin-bottom: 1rem; position: relative;">
            <div style="position: absolute; left: -1.5rem; top: 0.25rem; width: 0.75rem; height: 0.75rem; background: var(--primary); border-radius: 50%; border: 2px solid var(--bg-card);"></div>
            <div style="background: rgba(0,0,0,0.2); padding: 0.75rem; border-radius: 0.375rem;">
              <div style="font-weight: 600; color: var(--primary); font-size: 0.875rem;">${h.変更種別}</div>
              <div style="color: var(--text-muted); font-size: 0.75rem; margin-top: 0.25rem;">
                ${h.変更フィールド ? `フィールド: ${h.変更フィールド}` : ''}
              </div>
              ${h.変更前値 ? `<div style="color: var(--text-muted); font-size: 0.75rem;">変更前: ${h.変更前値}</div>` : ''}
              ${h.変更後値 ? `<div style="color: var(--text); font-size: 0.75rem;">変更後: ${h.変更後値}</div>` : ''}
              <div style="color: var(--text-muted); font-size: 0.75rem; margin-top: 0.25rem;">
                ${new Date(h.作成日時).toLocaleString('ja-JP')}
              </div>
            </div>
          </div>
        `).join("");

        historyPanel.style.display = 'block';
      }
    }

    // 削除ボタン
    const delBtn = e.target.closest(".delete-btn");
    if (delBtn) {
      if (!confirm("この資料を削除しますか？")) return;
      const recordId = delBtn.dataset.id;
      const record = allRecords.find(r => r.id === recordId);
      const tableIndex = record.契約書名 ? 0 : 1;

      await window.aivicApi.delete(tableIndex, recordId);
      allRecords = allRecords.filter(r => r.id !== recordId);
      renderRows(allRecords);
      historyPanel.style.display = 'none';
    }
  });

  // 履歴パネルを閉じる
  container.querySelector("#btn-close-history").addEventListener("click", () => {
    historyPanel.style.display = 'none';
  });

  // ===== CSVエクスポート =====
  container.querySelector("[data-testid='export-csv-button']").addEventListener("click", () => {
    if (allRecords.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ['資料名', '種別', 'ステータス', '作成日', '最終更新日'];
    const rows = allRecords.map(r => [
      r.契約書名 || r.提案資料名 || '',
      r.契約種別 ? '契約書' : '提案資料',
      r.ステータス || '',
      r.作成日時 ? new Date(r.作成日時).toLocaleDateString('ja-JP') : '',
      r.更新日時 ? new Date(r.更新日時).toLocaleDateString('ja-JP') : ''
    ]);

    const csv = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `資料検索結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス（契約書と提案資料を統合）
  const contractTableIndex = 0;  // 契約書
  const proposalTableIndex = 1;  // 提案資料
  const userTableIndex = 2;      // ユーザー（作成者フィルタ用）

  // 統合データ（契約書 + 提案資料）
  let allRecords = [];

  // 1. 再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#result-tbody");
    const countEl = container.querySelector("#result-count");

    countEl.textContent = rows.length;

    if (rows.length === 0) {
      tbody.innerHTML = `<tr style="height: 2rem;"><td colspan="6" style="padding: 1rem; text-align: center; color: var(--text-muted); font-size: 0.9rem;">検索結果がありません</td></tr>`;
      return;
    }

    tbody.innerHTML = rows.map(r => {
      const name = r.契約書名 || r.提案資料名 || "（名前なし）";
      const type = r.契約種別 ? "契約書" : "提案資料";
      const status = r.ステータス || "—";
      const creatorName = r.作成者名 || "—";
      const createdDate = r.作成日時 ? new Date(r.作成日時).toLocaleDateString("ja-JP") : "—";
      const recordId = r.契約書ID || r.提案資料ID || r.id;
      const isContract = !!r.契約書ID;

      return `
        <tr data-id="${recordId}" data-type="${isContract ? 'contract' : 'proposal'}" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.15s;">
          <td style="padding: 0.75rem; color: var(--text);">${name}</td>
          <td style="padding: 0.75rem; color: var(--text-muted); font-size: 0.9rem;">${type}</td>
          <td style="padding: 0.75rem;">
            <span style="display: inline-block; padding: 0.25rem 0.625rem; border-radius: 0.25rem; font-size: 0.85rem; font-weight: 600; background: ${getStatusBgColor(status)}; color: ${getStatusTextColor(status)};">
              ${status}
            </span>
          </td>
          <td style="padding: 0.75rem; color: var(--text-muted); font-size: 0.9rem;">${creatorName}</td>
          <td style="padding: 0.75rem; color: var(--text-muted); font-size: 0.9rem;">${createdDate}</td>
          <td style="padding: 0.75rem; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${recordId}" data-type="${isContract ? 'contract' : 'proposal'}" style="padding: 0.375rem 0.75rem; font-size: 0.85rem; border: 1px solid rgba(255,255,255,0.18); background: transparent; color: var(--text); cursor: pointer;">
              詳細
            </button>
          </td>
        </tr>
      `;
    }).join("");

    // 行ホバー効果
    tbody.querySelectorAll("tr").forEach(tr => {
      tr.addEventListener("mouseenter", () => {
        tr.style.background = "rgba(255,255,255,0.05)";
      });
      tr.addEventListener("mouseleave", () => {
        tr.style.background = "";
      });
    });
  }

  // ステータスの背景色
  function getStatusBgColor(status) {
    const colors = {
      "有効": "rgba(76, 175, 80, 0.2)",
      "契約済み": "rgba(76, 175, 80, 0.2)",
      "承認済み": "rgba(76, 175, 80, 0.2)",
      "承認待ち": "rgba(255, 193, 7, 0.2)",
      "レビュー中": "rgba(255, 193, 7, 0.2)",
      "提案中": "rgba(255, 193, 7, 0.2)",
      "草案": "rgba(158, 158, 158, 0.2)",
      "下書き": "rgba(158, 158, 158, 0.2)",
      "終了": "rgba(244, 67, 54, 0.2)",
      "キャンセル": "rgba(244, 67, 54, 0.2)",
      "却下": "rgba(244, 67, 54, 0.2)"
    };
    return colors[status] || "rgba(158, 158, 158, 0.2)";
  }

  function getStatusTextColor(status) {
    const colors = {
      "有効": "#4caf50",
      "契約済み": "#4caf50",
      "承認済み": "#4caf50",
      "承認待ち": "#ffc107",
      "レビュー中": "#ffc107",
      "提案中": "#ffc107",
      "草案": "#9e9e9e",
      "下書き": "#9e9e9e",
      "終了": "#f44336",
      "キャンセル": "#f44336",
      "却下": "#f44336"
    };
    return colors[status] || "#9e9e9e";
  }

  // 2. 初期データ読み込み
  async function loadInitialData() {
    try {
      // 契約書データ取得
      const contracts = await window.aivicApi.list(contractTableIndex);
      const contractRecords = (contracts || []).map(c => ({
        ...c,
        種別: "契約書",
        資料名: c.契約書名,
        作成者名: c.作成者 || "—"
      }));

      // 提案資料データ取得
      const proposals = await window.aivicApi.list(proposalTableIndex);
      const proposalRecords = (proposals || []).map(p => ({
        ...p,
        種別: "提案資料",
        資料名: p.提案資料名,
        作成者名: p.作成者 || "—"
      }));

      // ユーザーデータ取得（作成者フィルタ用）
      const users = await window.aivicApi.list(userTableIndex);
      const creatorSelect = container.querySelector("#select-creator");
      if (users && users.length > 0) {
        users.forEach(u => {
          const opt = document.createElement("option");
          opt.value = u.氏名 || u.ユーザー名;
          opt.textContent = u.氏名 || u.ユーザー名;
          creatorSelect.appendChild(opt);
        });
      }

      // 統合
      allRecords = [...contractRecords, ...proposalRecords];
      renderRows([]);
    } catch (err) {
      console.error("初期データ読み込みエラー:", err);
      renderRows([]);
    }
  }

  // 3. 検索フィルタ関数
  function applyFilters() {
    const keyword = container.querySelector("#input-keyword").value.toLowerCase();
    const type = container.querySelector("#select-type").value;
    const status = container.querySelector("#select-status").value;
    const creator = container.querySelector("#select-creator").value;
    const createdFrom = container.querySelector("#input-created-from").value;
    const createdTo = container.querySelector("#input-created-to").value;
    const updatedFrom = container.querySelector("#input-updated-from").value;
    const updatedTo = container.querySelector("#input-updated-to").value;

    let filtered = allRecords;

    // キーワード検索
    if (keyword) {
      filtered = filtered.filter(r => {
        const name = (r.契約書名 || r.提案資料名 || "").toLowerCase();
        const desc = (r.契約書説明 || r.説明 || "").toLowerCase();
        return name.includes(keyword) || desc.includes(keyword);
      });
    }

    // 種別フィルタ
    if (type) {
      filtered = filtered.filter(r => {
        if (type === "契約書") return !!r.契約書ID;
        if (type === "提案資料") return !!r.提案資料ID;
        return true;
      });
    }

    // ステータスフィルタ
    if (status) {
      filtered = filtered.filter(r => r.ステータス === status);
    }

    // 作成者フィルタ
    if (creator) {
      filtered = filtered.filter(r => r.作成者名 === creator);
    }

    // 作成日範囲フィルタ
    if (createdFrom) {
      const fromDate = new Date(createdFrom);
      filtered = filtered.filter(r => {
        const rDate = new Date(r.作成日時);
        return rDate >= fromDate;
      });
    }
    if (createdTo) {
      const toDate = new Date(createdTo);
      toDate.setHours(23, 59, 59, 999);
      filtered = filtered.filter(r => {
        const rDate = new Date(r.作成日時);
        return rDate <= toDate;
      });
    }

    // 更新日範囲フィルタ
    if (updatedFrom) {
      const fromDate = new Date(updatedFrom);
      filtered = filtered.filter(r => {
        const rDate = new Date(r.更新日時);
        return rDate >= fromDate;
      });
    }
    if (updatedTo) {
      const toDate = new Date(updatedTo);
      toDate.setHours(23, 59, 59, 999);
      filtered = filtered.filter(r => {
        const rDate = new Date(r.更新日時);
        return rDate <= toDate;
      });
    }

    renderRows(filtered);
  }

  // 4. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", () => {
    applyFilters();
  });

  // 5. リセットボタンのイベントリスナー
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#input-keyword").value = "";
    container.querySelector("#select-type").value = "";
    container.querySelector("#select-status").value = "";
    container.querySelector("#select-creator").value = "";
    container.querySelector("#input-created-from").value = "";
    container.querySelector("#input-created-to").value = "";
    container.querySelector("#input-updated-from").value = "";
    container.querySelector("#input-updated-to").value = "";
    renderRows([]);
  });

  // 6. CSVエクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", () => {
    const tbody = container.querySelector("#result-tbody");
    const rows = Array.from(tbody.querySelectorAll("tr"));

    if (rows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    // ヘッダー
    const headers = ["資料名", "種別", "ステータス", "作成者", "作成日"];
    const csvContent = [
      "\uFEFF" + headers.map(h => `"${h}"`).join(","),
      ...rows.map(tr => {
        const cells = tr.querySelectorAll("td");
        return [
          cells[0].textContent.trim(),
          cells[1].textContent.trim(),
          cells[2].textContent.trim(),
          cells[3].textContent.trim(),
          cells[4].textContent.trim()
        ].map(c => `"${c.replace(/"/g, '""')}"`).join(",");
      })
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `contract-proposal-search-${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
  });

  // 7. 詳細ボタンのイベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const recordId = detailBtn.dataset.id;
      const recordType = detailBtn.dataset.type;

      // 詳細画面へ遷移（契約書管理画面または提案資料管理画面）
      if (recordType === "contract") {
        window.showScreen("scr-1781954440904"); // 契約書管理画面
      } else {
        window.showScreen("scr-1781954457288"); // 提案資料管理画面
      }
    }
  });

  // 8. 初期化
  loadInitialData();
}

